const HTML="<!doctype html><html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#faf6f2\"><title>Pok\u00e9amor \u00b7 Un flechazo a la vez</title><style>@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@1,500&display=swap');\n:root{font-family:'DM Sans',sans-serif;color:#292a26;background:#15191b;font-synthesis:none;--yes-intent:0;--no-intent:0}*{box-sizing:border-box}body{margin:0;height:100dvh;overflow:hidden}button,a,input{font:inherit}button{cursor:pointer;border:0;color:inherit;touch-action:manipulation;-webkit-tap-highlight-color:transparent}button:focus-visible,a:focus-visible{outline:2px solid #df9fb7;outline-offset:4px}button:disabled{opacity:.24;cursor:default}\n.world,.ambient,.decision-glow{position:fixed;inset:0;pointer-events:none}.world{z-index:0;background:#171b1e}.ambient{opacity:0;transition:opacity .6s ease;will-change:opacity;background:radial-gradient(ellipse at 50% 40%,#364749,transparent 75%)}\n#app{position:relative;height:100dvh;min-height:0;max-width:540px;margin:auto;display:flex;flex-direction:column;padding:max(4px,env(safe-area-inset-top)) 4px max(5px,env(safe-area-inset-bottom));overflow:hidden;isolation:isolate;z-index:1;color:#f5f1eb}\nheader{display:flex;align-items:center;justify-content:space-between;gap:12px}#app>header{display:grid;grid-template-columns:60px 1fr 60px;height:44px;min-height:44px;padding:0 8px;z-index:8}#app>header>div{text-align:center}.brand{font-size:21px;letter-spacing:-.8px;font-weight:600}.brand span{color:#ba667d}#app .brand{font-size:15px;font-weight:400;color:#ffffff68;letter-spacing:-.5px}#app .brand span{color:inherit}#app .brand>span:last-child{display:none}\n.undo{width:44px;height:44px;font-size:22px;background:transparent;color:#ffffff8a;transition:transform .2s}.undo:active{transform:rotate(-35deg)}.collection{background:transparent;padding:0 4px;min-height:44px;min-width:54px;justify-self:end;color:#ffffffa6;font-size:12px;font-variant-numeric:tabular-nums}.collection b{font-weight:500}.collection.bump{animation:collection-bump .32s ease}\n.stage{position:relative;display:flex;flex:1;min-height:0;justify-content:center;align-items:center;perspective:1300px;touch-action:none;overflow:visible}\n.card{position:absolute;width:var(--card-width,100%);aspect-ratio:.716;border-radius:15px;transform-origin:50% 65%;backface-visibility:hidden;box-shadow:0 2px 3px #0004,0 20px 38px -20px #000c;touch-action:none;user-select:none;-webkit-touch-callout:none;will-change:transform;background:transparent;overflow:hidden;z-index:2;cursor:grab;isolation:isolate;transition:box-shadow .2s}\n.card:active{cursor:grabbing}.card img{width:100%;height:100%;object-fit:contain;display:block;pointer-events:none}.card::after{content:'';position:absolute;inset:0;border-radius:inherit;box-shadow:inset 0 0 0 1px #ffffff70;pointer-events:none;z-index:5}.card.official{background:radial-gradient(ellipse at top,#eee8dd,#bfcfc7)}.card.official img{padding:25px}.card.under{z-index:1;pointer-events:none;transform:translateY(6px) scale(.972);filter:brightness(.8);box-shadow:0 8px 18px -8px #0006;transition:transform .15s,filter .15s}.card.exiting{z-index:6}.card.lifted{box-shadow:0 3px 3px #0002,0 25px 45px -17px #000b,0 45px 60px -30px #0005}\n.card .glint,.card .foil,.choice-light{position:absolute;inset:0;pointer-events:none;border-radius:inherit}.card .glint{opacity:0;background:radial-gradient(ellipse at var(--x,50%) var(--y,35%),#ffffff40,#ffffff0a 25%,transparent 58%);mix-blend-mode:screen;transition:opacity .2s}.card.active .glint{opacity:1}\n.card .foil{opacity:0;background:radial-gradient(ellipse at var(--x,50%) var(--y,50%),#ffffff90,transparent 43%),conic-gradient(from var(--angle,110deg) at var(--x,50%) var(--y,50%),transparent 0deg,#ffd7a444 40deg,#ccf7e84a 65deg,#b9b3f85a 90deg,transparent 125deg,transparent 235deg,#ffc6d240 275deg,#9ddce140 310deg,transparent 350deg);filter:saturate(.8);mix-blend-mode:color-dodge;transition:opacity .2s}.card.active .foil{opacity:.55}\n.choice-light{z-index:3;background:linear-gradient(90deg,rgb(147 204 234 / calc(var(--pass,0) * .4)),transparent 35%,transparent 65%,rgb(255 189 211 / calc(var(--love,0) * .46)));box-shadow:inset -3px 0 10px rgb(255 203 220 / var(--love,0)),inset 3px 0 10px rgb(160 218 247 / var(--pass,0));transition:opacity .12s}\n.stamp{position:absolute;top:20px;width:40px;height:40px;display:grid;place-items:center;font:34px/1 Arial,sans-serif;opacity:0;pointer-events:none;text-shadow:0 0 12px currentColor,0 1px 4px #0004;z-index:4;transition:opacity .07s,transform .1s}\n.controls{display:grid;grid-template-columns:44px 1fr 44px;align-items:center;height:44px;min-height:44px;margin:0 auto;width:min(100%,380px);padding:0 10px;z-index:7}.vote{width:44px;height:44px;background:transparent;color:#fff8;display:grid;place-items:center;border-radius:50%;padding:0;box-shadow:none;transition:color .13s,transform .13s}.vote span{font:24px/1 Arial,sans-serif}.vote.no{order:1}.vote.yes{order:3}.vote.ready{color:#ffd4e4;transform:scale(1.16)}.vote.no.ready{color:#b8e2f4}.vote:active{transform:scale(.86)}.caption{order:2;text-align:center;min-width:0}.caption strong{font-size:11px;font-weight:400;letter-spacing:.15px;color:#ffffff88}.caption small,.caption .dex{display:none}\n.track{position:fixed;bottom:0;left:0;right:0;height:1px;z-index:1;background:transparent}.track i{display:block;height:100%;background:#ffffff38;transition:width .2s}.foot{position:absolute;height:1px;width:1px;clip-path:inset(50%);overflow:hidden}\n.decision-glow{z-index:3;isolation:isolate}.decision-glow::before,.decision-glow::after{content:'';position:absolute;inset:0;opacity:0;transition:opacity .1s}.decision-glow::before{background:radial-gradient(ellipse at 100% 48%,#f4a8c86b,transparent 67%);opacity:var(--yes-intent)}.decision-glow::after{background:radial-gradient(ellipse at 0% 48%,#8cc9ea66,transparent 67%);opacity:var(--no-intent)}\n.decision-glow .sigil{position:absolute;top:45%;color:#ffe5ef;font:40px/1 Arial,sans-serif;opacity:0;text-shadow:0 0 22px #ef92b6;display:grid;place-items:center;width:48px;height:48px}.decision-glow .sigil.yes{right:9px}.decision-glow .sigil.no{left:9px;color:#c6ebfa;text-shadow:0 0 22px #8dcdeb}.decision-glow.confirm-yes::before{animation:decision-bloom .52s ease-out}.decision-glow.confirm-no::after{animation:decision-bloom .42s ease-out}.decision-glow.confirm-yes .sigil.yes,.decision-glow.confirm-no .sigil.no{animation:decision-sigil .48s ease-out}\n@keyframes decision-bloom{0%{opacity:.95}100%{opacity:0}}@keyframes decision-sigil{0%{opacity:0;transform:translateY(8px) scale(.7)}20%{opacity:1;transform:translateY(0) scale(1)}100%{opacity:0;transform:translateY(-20px) scale(.9)}}\n@keyframes collection-bump{40%{transform:scale(1.15)}100%{transform:scale(1)}}\n.card.dealt{animation:deal-in .2s cubic-bezier(.18,.8,.2,1) both}.card.returned{animation:card-return .25s cubic-bezier(.18,.8,.2,1) both}@keyframes deal-in{from{transform:translateY(6px) scale(.972)}to{transform:translateY(0) scale(1)}}@keyframes card-return{from{transform:translateX(-35px) rotate(-3deg);opacity:.5}to{transform:translateX(0) rotate(0);opacity:1}}\n.sheet{position:fixed;inset:0;background:#f5f2ec;color:#292a26;z-index:10;overflow:auto;padding:max(24px,env(safe-area-inset-top)) 22px max(26px,env(safe-area-inset-bottom));display:none}.sheet.open{display:block}.inner{max-width:740px;margin:auto}.sheet header{position:sticky;top:0;background:#f5f2ec;z-index:1;padding:8px 0 16px}.sheet h2,dialog h2{font-family:'Playfair Display',Georgia,serif;font-weight:500;font-style:italic;font-size:34px;margin:25px 0 8px}.muted{color:#818379;font-size:12px;line-height:1.7}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.pill{background:#e7e7de;border-radius:20px;padding:10px 14px;font-size:12px}.pill.selected{background:#343d32;color:#fff}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px 10px}.tile{background:none;text-align:left;padding:0;position:relative}.tile img{width:100%;aspect-ratio:.716;object-fit:contain;border-radius:8px;background:#e7e8df}.tile b{font-size:11px;display:block;margin:5px 0}.tile small{font-size:9px;color:#7a8174}.rank{position:absolute;top:5px;left:5px;background:#fff;border-radius:20px;padding:5px 7px;font-size:10px}.tools{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0}.duels{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:24px 0}.duels button{padding:0;background:none}.duels img{width:100%;border-radius:10px}.toast{position:fixed;bottom:calc(env(safe-area-inset-bottom) + 80px);left:50%;transform:translateX(-50%);background:#303b31ed;color:#fff;padding:10px 15px;border-radius:30px;font-size:11px;z-index:20;pointer-events:none;opacity:0;transition:opacity .2s;max-width:90%;text-align:center}.toast.show{opacity:1}.close{border-radius:50%;width:38px;height:38px;background:#e7e7de}a{color:#a24f69}dialog{border:0;border-radius:20px;background:#f5f2ec;max-width:390px;width:90%;padding:25px}dialog::backdrop{background:#10161ab3}input[type=text]{width:100%;padding:12px;border:1px solid #d4d5cb;border-radius:10px;background:white;margin:12px 0;font-size:12px}.sensory{display:flex;gap:18px;flex-wrap:wrap;padding:14px 0;border-top:1px solid #dedfd5;border-bottom:1px solid #dedfd5}.sensory label{display:flex;align-items:center;gap:10px;font-size:12px;color:#70786a}.sensory input{accent-color:#b85d78;cursor:pointer;min-width:32px;min-height:24px}.haptic-bridge{position:fixed;left:-100px;top:0;width:1px;height:1px;overflow:hidden;opacity:0;pointer-events:none}\n@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}.decision-glow .sigil{display:none}.decision-glow.confirm-yes::before,.decision-glow.confirm-no::after{opacity:.45}}\n\n/* Soft daylight, with a short, readable confirmation for each decision. */\n:root{background:#faf6f2}body,.world{background:#faf6f2}.ambient{background:radial-gradient(ellipse at 50% 40%,#e9e4f0,transparent 75%)}\n#app{color:#554e51}#app .brand{color:#9c9297}.undo{color:#a4979c}.collection{color:#b06e8c}.vote{color:#a8a1a6}.vote.yes{color:#bd7c97}.vote.ready{color:#bf5d87}.vote.no.ready{color:#749bab}.caption strong{color:#928a90}.track i{background:#c696ad55}\n.card{box-shadow:0 2px 3px #684e5d12,0 16px 34px -20px #7b5b7466}.card.under{filter:brightness(.98);box-shadow:0 8px 16px -8px #85677933}.card.lifted{box-shadow:0 3px 3px #765e6910,0 22px 38px -17px #80687966,0 38px 55px -30px #80687933}\n.decision-glow .sigil{top:var(--origin-y,50%);left:var(--origin-x,70%);right:auto;margin:-25px 0 0 -25px;width:50px;height:50px;border-radius:50%;background:#fff6fae8;color:#ca7399;text-shadow:none;box-shadow:0 4px 20px #bd729c20;border:1px solid #ffffffcc;will-change:transform,opacity}\n.decision-glow .sigil.yes{right:auto}.decision-glow .sigil.no{left:var(--origin-x,30%);right:auto;background:#f6fbfde8;color:#89a7b4;text-shadow:none;font-size:27px;box-shadow:0 4px 16px #93aebb18}\n.decision-glow.confirm-yes .sigil.yes{animation:heart-to-collection .62s cubic-bezier(.2,.65,.3,1) both}.decision-glow.confirm-no .sigil.no{animation:bubble-away .4s ease-out both}\n.decision-glow .sigil.no::after{content:'';position:absolute;inset:0;border-radius:50%;border:1px solid #9bb9c3;opacity:0}.decision-glow.confirm-no .sigil.no::after{animation:bubble-ring .4s ease-out}\n@keyframes heart-to-collection{0%{opacity:0;transform:scale(.45) rotate(-12deg)}18%{opacity:1;transform:translateY(-5px) scale(1.12) rotate(6deg)}35%{opacity:1;transform:translateY(-12px) scale(.95) rotate(0)}85%{opacity:.9}100%{opacity:0;transform:translate(var(--travel-x,0px),var(--travel-y,-220px)) scale(.2) rotate(-8deg)}}\n@keyframes bubble-away{0%{opacity:0;transform:scale(.55)}22%{opacity:1;transform:scale(1.03)}65%{opacity:.7}100%{opacity:0;transform:translate(-24px,-12px) scale(.7)}}\n@keyframes bubble-ring{0%{opacity:.5;transform:scale(.85)}100%{opacity:0;transform:scale(1.65)}}\n@media(prefers-reduced-motion:reduce){.decision-glow .sigil{display:grid}.decision-glow.confirm-yes .sigil.yes,.decision-glow.confirm-no .sigil.no{opacity:1}.decision-glow.confirm-yes::before,.decision-glow.confirm-no::after{opacity:.2}}\n\n/* A paper edge rather than a dark sleeve; feedback stays legible on pastel. */\n.card{background:transparent;box-shadow:0 1px 2px #997c8c10,0 9px 22px -13px #a18a9c42}\n.card::after{box-shadow:inset 0 0 0 1px #fff9}\n.card.under{background:var(--card-paper,#faf4f7);filter:none;transform:translateY(4px) scale(.98);box-shadow:0 2px 4px #b19aa921}\n.card.under img{opacity:0}.card.under::after{box-shadow:inset 0 0 0 1px #fff9}\n.card.lifted{box-shadow:0 3px 5px #a08a9812,0 17px 29px -16px #a08a9852}\n.stamp{background:#fffafdf0;border-radius:50%;text-shadow:none;box-shadow:0 2px 10px #b3849e1f}\n.decision-glow .sigil{background:#fffafd;color:#a93865;border:1.5px solid #e8a5be;box-shadow:0 3px 14px #b45b8429;width:52px;height:52px;margin:-26px 0 0 -26px}\n.decision-glow .sigil.no{background:#f8fcfd;color:#4f7586;border-color:#a9c7d4;box-shadow:0 3px 14px #739aae24;font-weight:500}\n.decision-glow .sigil.no::after{border-color:#7da7b9}\n.decision-glow.confirm-yes .sigil.yes{animation:heart-to-collection .7s cubic-bezier(.25,.6,.35,1) both}\n.decision-glow.confirm-no .sigil.no{animation:bubble-away .48s ease-out both}\n.decision-glow.confirm-no .sigil.no::after{animation:bubble-ring .48s ease-out}\n@keyframes heart-to-collection{0%{opacity:0;transform:scale(.6) rotate(-10deg)}12%{opacity:1;transform:translateY(-4px) scale(1.1) rotate(4deg)}30%{opacity:1;transform:translateY(-8px) scale(1) rotate(0)}75%{opacity:1}100%{opacity:0;transform:translate(var(--travel-x,0px),var(--travel-y,-220px)) scale(.28)}}\n@keyframes bubble-away{0%{opacity:0;transform:scale(.65)}16%{opacity:1;transform:scale(1.06)}44%{opacity:1;transform:translate(-3px,-2px) scale(1)}100%{opacity:0;transform:translate(-24px,-12px) scale(.75)}}\n@media(prefers-reduced-motion:reduce){.decision-glow.confirm-yes .sigil.yes,.decision-glow.confirm-no .sigil.no{animation:none!important;opacity:1}}\n\n/* Opaque, outlined badges remain readable over both pale and busy card art. */\n.stamp{top:22px;width:66px;height:66px;background:#fffdfd;border:2px solid currentColor;border-radius:50%;box-shadow:0 0 0 3px #fffdfdcc,0 5px 16px #865b7533;text-shadow:none;transition:opacity .06s,transform .1s;isolation:isolate}\n.stamp svg{width:35px;height:35px;display:block}.stamp .heart{display:none}.stamp.love .heart{display:block}.stamp.love .cross{display:none}.stamp.armed{animation:feedback-lock .18s ease-out}\n.choice-light{background:linear-gradient(90deg,rgb(64 137 169 / calc(var(--pass,0) * .36)),transparent 40%,transparent 60%,rgb(208 75 130 / calc(var(--love,0) * .35)));box-shadow:inset -4px 0 14px rgb(220 108 154 / var(--love,0)),inset 4px 0 14px rgb(97 161 190 / var(--pass,0))}\n@keyframes feedback-lock{0%{transform:scale(.94)}55%{transform:scale(1.1)}100%{transform:scale(1)}}\n@media(prefers-reduced-motion:reduce){.stamp.armed{animation:none!important}}\n</style></head><body><div class=\"world\" aria-hidden=\"true\"><div class=\"ambient\" id=\"ambient-a\"></div><div class=\"ambient\" id=\"ambient-b\"></div></div><div class=\"decision-glow\" id=\"decision-glow\" aria-hidden=\"true\"><span class=\"sigil yes\"><svg viewBox=\"0 0 24 24\" width=\"29\" height=\"29\" fill=\"currentColor\"><path d=\"M12 21s-9-5.5-9-12a5 5 0 0 1 9-3 5 5 0 0 1 9 3c0 6.5-9 12-9 12Z\"/></svg></span><span class=\"sigil no\">\u00d7</span></div><main id=\"app\"><header><button class=\"undo\" id=\"undo\" aria-label=\"Deshacer \u00faltima elecci\u00f3n\">\u21b6</button><div><div class=\"brand\">pok\u00e9<span>amor</span><span style=\"font-size:14px;margin-left:4px\">\u2727</span></div></div><button class=\"collection\" id=\"open\" aria-label=\"Abrir mi colecci\u00f3n\"><b id=\"likes\">\u2661 0</b></button></header><div class=\"stage\" id=\"stage\"></div><div class=\"controls\"><div class=\"caption\"><div><strong id=\"name\"></strong><small id=\"art\"></small></div><span class=\"dex\" id=\"dex\"></span></div><button class=\"vote no\" id=\"no\" aria-label=\"Paso\"><span aria-hidden=\"true\">\u00d7</span></button><button class=\"vote yes\" id=\"yes\" aria-label=\"Me gusta\"><span aria-hidden=\"true\">\u2661</span></button></div><div class=\"track\"><i id=\"progress\"></i></div><div class=\"foot\"><span id=\"count\"></span><span id=\"save\" role=\"status\">Guardado en este iPhone</span></div></main><section class=\"sheet\" id=\"sheet\"><div class=\"inner\"><header><div class=\"brand\">Tu colecci\u00f3n <span>\u2661</span></div><button class=\"close\" id=\"close\" aria-label=\"Volver a elegir\">\u00d7</button></header><h2>Tus elegidos.</h2><p class=\"muted\" id=\"summary\"></p><div class=\"tools\"><button class=\"pill selected\" id=\"duel\">\u2727 Elegir mis favoritos</button><button class=\"pill\" id=\"share\">Compartir / recuperar</button><button class=\"pill\" id=\"export\">Exportar</button><button class=\"pill\" id=\"import\">Importar</button><input type=\"file\" id=\"file\" accept=\"application/json\" hidden></div><div class=\"sensory\"><label><span>Sonido</span><input id=\"sound-setting\" type=\"checkbox\" switch></label><label><span>Respuesta t\u00e1ctil</span><input id=\"touch-setting\" type=\"checkbox\" switch></label></div><div class=\"tabs\" id=\"tabs\"><button class=\"pill selected\" data-filter=\"yes\">Me gustan</button><button class=\"pill\" data-filter=\"no\">Pas\u00e9</button><button class=\"pill\" data-filter=\"pending\">Pendientes</button><button class=\"pill\" data-filter=\"top\">Finalistas</button></div><p class=\"muted\">Toc\u00e1 un Pok\u00e9mon para revisar tu elecci\u00f3n.</p><div class=\"grid\" id=\"grid\"></div><p class=\"muted\" style=\"margin-top:35px\">Orden de descubrimiento aproximado: favoritos conocidos primero y despu\u00e9s el resto del cat\u00e1logo. No representa un ranking completo de votos. Ilustraciones: Pok\u00e9mon TCG / TCGdex. Pok\u00e9mon pertenece a sus respectivos titulares.</p></div></section><section class=\"sheet\" id=\"duelsheet\"><div class=\"inner\"><header><span class=\"brand\">Un flechazo mayor.</span><button class=\"close\" id=\"endduel\" aria-label=\"Cerrar duelos\">\u00d7</button></header><h2>\u00bfCu\u00e1l te gusta m\u00e1s?</h2><div class=\"duels\" id=\"pair\"></div><div class=\"tools\"><button class=\"pill\" id=\"both\">Ambos \u2661</button><button class=\"pill\" id=\"skip\">No s\u00e9, siguiente</button></div><p class=\"muted\" id=\"duelcount\"></p></div></section><dialog id=\"sharing\"><h2>Tu colecci\u00f3n, a salvo.</h2><p class=\"muted\">Este enlace privado permite recuperar y editar tu colecci\u00f3n en otro dispositivo. Compartilo solamente con quien quieras darle acceso.</p><input id=\"link\" type=\"text\" readonly aria-label=\"Enlace de recuperaci\u00f3n\"><div class=\"tools\"><button class=\"pill selected\" id=\"copy\">Copiar enlace</button><button class=\"pill\" id=\"dismiss\">Listo</button></div><p class=\"muted\" id=\"cloudstatus\"></p></dialog><div class=\"haptic-bridge\" aria-hidden=\"true\"><label id=\"haptic-trigger\" for=\"haptic-native\"></label><input id=\"haptic-native\" type=\"checkbox\" switch tabindex=\"-1\"></div><div class=\"toast\" id=\"toast\" role=\"status\"></div><script src=\"/app.js\" defer></script></body></html>\n";
